/** 익명화된 FK 목록: [부모 테이블 인덱스, 자식 테이블 인덱스] (중복 FK 포함) */
const ANONYMIZED_RELATIONS: Array<[number, number]> = [
  [1, 2],
  [7, 2],
  [13, 14],
  [13, 14],
  [11, 14],
  [16, 15],
  [13, 15],
  [13, 15],
  [15, 17],
  [15, 17],
  [15, 17],
  [11, 17],
  [21, 22],
  [31, 22],
  [21, 23],
  [31, 23],
  [21, 25],
  [25, 26],
  [21, 27],
  [20, 28],
  [28, 29],
  [28, 30],
  [20, 32],
  [31, 32],
  [29, 33],
  [29, 33],
  [31, 34],
];

/**
 * 익명화 fixture로 ERD 노드와 엣지를 만든다.
 *
 * @returns 노드(초기 좌표 0,0)와 부모 -> 자식 방향 엣지
 */
export function buildAnonymizedRealDiagram(): { nodes: Node<TableNodeData>[]; edges: Edge[] } {
  const nodes: Node<TableNodeData>[] = ANONYMIZED_TABLES.map((table, tableIndex) => {
    const id = `t${String(tableIndex).padStart(2, '0')}`;
    const name = `${id}${'x'.repeat(Math.max(0, table.nameLength - id.length))}`;
    return {
      id,
      type: 'table',
      position: { x: 0, y: 0 },
      data: {
        label: name,
        logicalTableName: name,
        columns: table.columns.map(([length, pk], columnIndex) => {
          const columnName = `c${columnIndex}${'x'.repeat(Math.max(0, length - 2))}`;
          return {
            id: `${id}_c${columnIndex}`,
            name: columnName,
            logicalName: columnName,
            type: 'varchar',
            pk: pk === 1,
            nullable: pk !== 1,
          };
        }),
      },
    };
  });
  const edges: Edge[] = ANONYMIZED_RELATIONS.map(([parent, child], index) => ({
    id: `e${index}`,
    source: nodes[parent].id,
    target: nodes[child].id,
    type: 'erdRelation',
  }));

  return { nodes, edges };
}
